// stop the OOM-kills on the 4 GB pod
func init() {
    debug.SetGCPercent(400) // collect less often -> fewer pauses
}

var bufPool = sync.Pool{
    New: func() any { return new(bytes.Buffer) },
}

func handle(w http.ResponseWriter, r *http.Request) {
    buf := bufPool.Get().(*bytes.Buffer)
    buildResponse(buf, r)        // appends this request's data
    w.Write(buf.Bytes())
    bufPool.Put(buf)
}
